import random
def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_last = history[-1][1]
    if n < 10:
        return 'C' if opp_last == 'C' else 'D'
    if n < 20:
        opp_defections = sum(1 for h in history if h[1] == 'D')
        my_defections = sum(1 for h in history if h[0] == 'D')
        if opp_defections == 0:
            return 'C'
        if opp_defections > my_defections:
            return 'D'
        return 'C' if opp_last == 'C' else 'D'
    opp_actions = [h[1] for h in history]
    my_actions = [h[0] for h in history]
    opp_defects = sum(1 for a in opp_actions if a == 'D')
    my_defects = sum(1 for a in my_actions if a == 'D')
    recent = opp_actions[-10:]
    recent_defects = sum(1 for a in recent if a == 'D')
    if recent_defects == 0:
        return 'C'
    if recent_defects >= 8:
        return 'D'
    if opp_defects == 0:
        return 'C'
    opp_defect_rate = opp_defects / n
    if opp_defect_rate < 0.15:
        return 'C'
    if opp_defect_rate > 0.6:
        return 'D'
    last5 = opp_actions[-5:]
    if last5 and all(a == 'C' for a in last5):
        return 'C'
    if len(last5) >= 2 and last5[-1] == 'D' and last5[-2] == 'D':
        return 'D'
    if opp_defects > my_defects + 2:
        return 'D'
    if opp_last == 'D':
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    return 'C'
